    "voice": [
      {
        "id": "none",
        "label": "No author voice",
        "default": true,
        "text": "",
        "help": ""
      },
      {
        "id": "austen",
        "label": "Jane Austen",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Jane Austen. Free indirect irony that slides into {{char}}'s judgments and gently exposes them; precise social observation; balanced sentences; wit in dialogue; feeling revealed through manners.",
        "help": "Free indirect irony, social wit."
      },
      {
        "id": "kleypas",
        "label": "Lisa Kleypas",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Lisa Kleypas. Lush but clear historical romance; strong sensual tension and frank desire; humor between lovers; emotionally honest leads; rich period texture that never drowns the scene.",
        "help": "Lush, frank historical romance."
      },
      {
        "id": "gabaldon",
        "label": "Diana Gabaldon",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Diana Gabaldon. Sweeping, earthy, physical storytelling; sensory detail of food, dirt, weather and bodies; frank sexuality; humor amid hardship; deep partnership intimacy; history worn lightly.",
        "help": "Earthy, sensory, sweeping."
      },
      {
        "id": "rooney",
        "label": "Sally Rooney",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Sally Rooney. Spare, precise contemporary prose; conversations that avoid their real subject; acute attention to power, class and misunderstanding between intimates; feeling carried by small gestures and what isn't said. Dialogue stays in quotes.",
        "help": "Spare, precise, avoidant intimacy."
      },
      {
        "id": "henry",
        "label": "Emily Henry",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Emily Henry. Fast, funny banter with an emotional undertow; specific everyday and pop-culture detail; tension built through rivalry and running jokes; vulnerability arriving suddenly inside a joke.",
        "help": "Banter with an undertow."
      },
      {
        "id": "french",
        "label": "Tana French",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Tana French. Psychologically dense interiority; a focal mind that misreads itself; atmosphere tied to place and memory; long rhythmic sentences cut by sharp short ones; dialogue that circles and probes.",
        "help": "Dense interiority, place and memory."
      },
      {
        "id": "flynn",
        "label": "Gillian Flynn",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Gillian Flynn. Sharp, caustic, unsentimental; ugly honest thoughts; dark humor; domestic surfaces hiding violence; unnerving reveals.",
        "help": "Caustic, dark, unnerving."
      },
      {
        "id": "jackson",
        "label": "Shirley Jackson",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Shirley Jackson. Quiet domestic unease; ordinary sentences carrying dread; politeness hiding hostility; the uncanny arriving through small social wrongness.",
        "help": "Quiet domestic dread."
      },
      {
        "id": "du_maurier",
        "label": "Daphne du Maurier",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Daphne du Maurier. Brooding romantic suspense; houses with memory; jealousy, obsession and class; landscape as a presence without mood-mirroring; a slowly tightening grip.",
        "help": "Brooding romantic suspense."
      },
      {
        "id": "tartt",
        "label": "Donna Tartt",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Donna Tartt. Lush, intelligent, melancholy; obsessive attention to objects, beauty and moral decay; a focal mind seduced by people it should fear; long elegant sentences.",
        "help": "Lush, intelligent, melancholy."
      },
      {
        "id": "ishiguro",
        "label": "Kazuo Ishiguro",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Kazuo Ishiguro. Restraint and evasion; a focal mind that steps around the painful truth; calm surfaces over enormous pressure; understatement that devastates.",
        "help": "Restraint over pressure."
      },
      {
        "id": "le_guin",
        "label": "Ursula K. Le Guin",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Ursula K. Le Guin. Clear, humane, anthropological; cultures with coherent customs; plain words carrying large ideas; moral seriousness without preaching.",
        "help": "Clear, humane, anthropological."
      },
      {
        "id": "chandler",
        "label": "Raymond Chandler",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Raymond Chandler. Hard-boiled cynicism carried in {{char}}'s thoughts; vivid, specific, wisecracking observation; clipped dialogue; a city full of liars. At most one striking comparison per beat.",
        "help": "Hard-boiled, wisecracking."
      },
      {
        "id": "mccarthy",
        "label": "Cormac McCarthy",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Cormac McCarthy. Stark, biblical cadence; long chained sentences of physical action joined by 'and'; sparse, laconic dialogue (still in quotes); landscape and violence rendered without comment.",
        "help": "Stark, chained, laconic."
      },
      {
        "id": "rice",
        "label": "Anne Rice",
        "text": "- Author voice (technique only, never quotation or pastiche of the text): Anne Rice. Opulent, sensual, confessional; beauty and hunger intertwined; rich material detail; intense emotional and erotic interiority in {{char}}'s thoughts.",
        "help": "Opulent, sensual, confessional."
      }
    ],
