      "reasoning_match": [
        "thinking",
        ":think"
      ],
      "note": {
        "loud": "Note to self, Kimi brain edition:\n- If I think first: short and decisive. Trust the plan and write; don't litigate every rule.\n- Banned habits: stacks of one-line paragraphs for Drama; fragments in threes; a punchline closing every paragraph; over-formatting. Full paragraphs that actually flow.",
        "plain": "- If you plan first, keep it short and decisive, then write; do not re-argue each rule.\n- Avoid: stacks of one-line paragraphs for effect; fragments in threes; a punchline closing every paragraph; over-formatting. Write full paragraphs that flow."
      },
      "samplers": {
        "temperature": 0.8,
        "top_p": 0.95,
        "frequency_penalty": 0,
        "presence_penalty": 0,
        "max_tokens": 8192
      },
      "reasoning_effort": "auto",
