export function optionList(ref, c = content) {
    const r = String(ref || '');
    if (r === 'personas') return c.personas.map(p => ({ id: p.id, label: p.label || p.name, text: '', help: p.blurb || '', default: !!p.default }));
    if (r === 'models') return [{ id: 'auto', label: 'Auto-detect', text: '', help: 'From the connected model id.', default: true }, ...c.models.map(m => ({ id: m.id, label: m.label, text: '', help: '' }))];
    if (r.startsWith('story.') || r.startsWith('options.story.fields.')) {
        const f = c.options.story.fields.find(x => x.id === r.slice(r.lastIndexOf('.') + 1));
        return f ? f.options : [];
    }
    if (r.startsWith('options.')) {
        const list = c.options[r.slice(8)];
        return Array.isArray(list) ? list : [];
    }
    return [];
}

export function findOption(ref, id, c = content) {
    return optionList(ref, c).find(o => o.id === id) || null;
}

export function defaultOptionId(ref, c = content) {
    const list = optionList(ref, c);
    const d = list.find(o => o.default);
    return d ? d.id : (list[0] ? list[0].id : '');
}

export function matchModel(modelId, c = content) {
    const id = String(modelId || '').toLowerCase();
    if (id) {
        for (const m of c.models) {
            for (const src of m.match || []) {
                try { if (new RegExp(src, 'i').test(id)) return m; } catch { /* validated at sync time */ }
            }
        }
    }
    return c.models.find(m => m.id === 'generic');
}

export function reasoningFor(modelId, c, familyOverride) {
    const fam = familyOverride && familyOverride !== 'auto' ? (c.models.find(m => m.id === familyOverride) || matchModel(modelId, c)) : matchModel(modelId, c);
    const id = String(modelId || '');
    for (const src of fam.reasoning_match || []) {
        try { if (new RegExp(src, 'i').test(id)) return 'native'; } catch { /* validated at sync time */ }
    }
    return fam.reasoning === 'native' ? 'native' : 'prompted';
}

export function configLines(settings, c = content) {
    const s = settings || {};
    const out = [];
    for (const f of c.options.story.fields) {
        if (!f.line) continue;
        const raw = s['story.' + f.id] ?? f.default ?? '';
        const v = String(raw).trim();
        if (!v) continue;
        const opt = f.options.find(o => o.id === v);
        const text = opt ? opt.text : (f.free_text ? v : '');
        if (!text) continue;
        out.push('- ' + f.line.split('{value}').join(text));
    }
    return out.join('\n');
}

export function contentDefaults(c = content) {
    const d = {
        persona: (c.personas.find(p => p.default) || c.personas[0]).id,
        rule_voice: defaultOptionId('options.rule_voice', c),
        author_voice: defaultOptionId('options.voice', c),
        length: defaultOptionId('options.length', c),
        dialogue: defaultOptionId('options.dialogue', c),
        thoughts: defaultOptionId('options.thoughts', c),
        pronouns: defaultOptionId('options.pronouns', c),
        explicitness: defaultOptionId('options.explicitness', c),
        tone: defaultOptionId('options.tone', c),
        genre: defaultOptionId('options.genre', c),
        model_family: 'auto',
    };
    for (const f of c.options.story.fields) d['story.' + f.id] = f.default ?? '';
    return d;
}

export function contentPlaceholders(settings, ctx, c = content) {
    const s = { ...contentDefaults(c), ...(settings || {}) };
    const x = ctx || {};
    const voice = s.rule_voice === 'plain' ? 'plain' : 'loud';
    const persona = c.personas.find(p => p.id === s.persona) || c.personas.find(p => p.default) || c.personas[0];
    const fam = s.model_family && s.model_family !== 'auto' ? (c.models.find(m => m.id === s.model_family) || matchModel(x.modelId, c)) : matchModel(x.modelId, c);
    const opt = (list, id) => {
        const o = c.options[list].find(y => y.id === id) || c.options[list].find(y => y.default) || c.options[list][0];
        return o ? o.text : '';
    };
    const ban = (Array.isArray(x.banlist) ? x.banlist : []).map(b => String(b).trim()).filter(Boolean);
    return {
        'uc.persona_name': persona.name,
        'uc.persona_identity': persona['identity_' + voice] || '',
        'uc.persona_ooc': x.oocInPersona === false ? '' : (persona.ooc || ''),
        'uc.persona_taste': persona.taste || '',
        'uc.length_rule': opt('length', s.length),
        'uc.dialogue_rule': opt('dialogue', s.dialogue),
        'uc.thoughts_rule': opt('thoughts', s.thoughts),
        'uc.pronoun_rule': opt('pronouns', s.pronouns),
        'uc.explicitness_rule': opt('explicitness', s.explicitness),
        'uc.tone_rule': opt('tone', s.tone),
        'uc.genre_rule': opt('genre', s.genre),
        'uc.voice_rule': opt('voice', s.author_voice),
        'uc.config_lines': configLines(s, c),
        'uc.banlist': ban.length ? '- Also banned: ' + ban.join('; ') : '',
        'uc.model_note': (fam.note && fam.note[voice]) || '',
    };
}

export function fillText(text, values) {
    const v = values || {};
    const out = [];
    for (const line of String(text ?? '').split('\n')) {
        const names = [...line.matchAll(/\{\{uc\.([a-z0-9_]+)\}\}/g)].map(m => m[1]);
        if (names.length && names.every(n => !String(v['uc.' + n] ?? '').trim())) continue;
        out.push(line.replace(/\{\{uc\.([a-z0-9_]+)\}\}/g, (_, n) => String(v['uc.' + n] ?? '')));
    }
    return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

export function contentEnvelope(opts, c = content) {
    const o = opts || {};
    const env = c.slots.uc_envelope;
    const want = Array.isArray(o.blocks) ? new Set(o.blocks) : null;
    const blocks = c.envelope.blocks.filter(b => !want || want.has(b.id));
    const parts = [o.compact === false ? env.full : env.compact, '', env.open, ...blocks.map(b => b.template), env.close];
    const rules = blocks.filter(b => b.rule).map(b => '- ' + b.tag + ': ' + b.rule);
    return [...parts, ...rules].join('\n');
}

export function buildSlot(slotId, settings, ctx, c = content) {
    const s = { ...contentDefaults(c), ...(settings || {}) };
    const x = ctx || {};
    const voice = s.rule_voice === 'plain' ? 'plain' : 'loud';
    const ph = contentPlaceholders(s, x, c);
    const req = (c.slot_requires || {})[slotId];
    if (Array.isArray(req) && !req.some(n => String(ph[n] ?? '').trim())) return '';
    if (slotId === 'uc_intimacy' && s.explicitness === 'off' && x.keepIntimacyWhenOff !== true) return '';
    let text;
    if (slotId === 'uc_think') {
        const mode = x.thinkMode === 'native' || x.thinkMode === 'prompted' ? x.thinkMode : '';
        if (!mode) return '';
        text = c.slots.uc_think[voice === 'plain' ? mode + '_plain' : mode];
    } else if (slotId === 'uc_envelope') {
        text = contentEnvelope({ compact: x.compact, blocks: x.blocks }, c);
    } else {
        const slot = c.slots[slotId];
        if (!slot) return '';
        text = typeof slot === 'string' ? slot : slot[voice];
    }
    return fillText(text, ph);
}

export function buildStaticZone(settings, ctx, c = content) {
    const ids = ['uc_identity', 'uc_law', 'uc_format', 'uc_world', 'uc_intimacy', 'uc_prose', 'uc_config', 'uc_style', 'uc_model'];
    return ids.map(id => buildSlot(id, settings, ctx, c)).filter(Boolean).join('\n\n');
}

export function estimateTokens(text) {
    return Math.ceil(String(text || '').length / 3.5);
}
